const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const southJava = ee.Geometry.Point([110.2273416, -8.879787]); // Southern coastal
  const northJava = ee.Geometry.Point([109.953683, -5.741852]); // Northern Java Sea
  const date = '2019-08-04';
  const dateStart = ee.Date(date);
  const dateEnd = dateStart.advance(1, 'day');

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterDate(dateStart, dateEnd)
    .select('chlor_a');

  const colSize = collection.size().getInfo();
  console.log(`Images found for ${date}: ${colSize}`);

  if (colSize === 0) {
    console.log('No ocean color data available for this date.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get the image for this date
  const image = collection.first();

  // 3. Extract chlorophyll-a values at both locations
  const southStats = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southJava,
    scale: 4000,
    maxPixels: 1e9
  });

  const northStats = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northJava,
    scale: 4000,
    maxPixels: 1e9
  });

  const southChlor = southStats.get('chlor_a').getInfo();
  const northChlor = northStats.get('chlor_a').getInfo();

  // 4. Validation & Output
  console.log(`Southern Java (coastal): ${southChlor !== null ? southChlor.toFixed(4) : 'null'} mg/m³`);
  console.log(`Northern Java Sea: ${northChlor !== null ? northChlor.toFixed(4) : 'null'} mg/m³`);

  // Check for null or invalid values
  if (southChlor === null || northChlor === null) {
    console.log('No valid chlorophyll data at one or both locations.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for reasonable ranges (chlorophyll-a typically 0.01-100 mg/m³)
  if (isNaN(southChlor) || isNaN(northChlor) || 
      southChlor < 0 || southChlor > 200 || 
      northChlor < 0 || northChlor > 200) {
    console.log('Invalid chlorophyll concentration values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 5. Final Answer
  if (southChlor > northChlor) {
    console.log('Southern coastal waters have higher chlorophyll-a.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Northern Java Sea waters have equal or higher chlorophyll-a.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
